<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { readFeature, writeFeature, featureError, type Classroom, type Assignment, type Attempt, type Feedback, type Page } from '@/services/additionalFeatures'
import { gatewayUrl } from '@/api/authApi'
import { plain } from '@/services/operationsApi'
import { useLatestRequest } from '@/services/latestRequest'
import OpsPager from './OpsPager.vue'
import './operations.css'
interface Member { id:number;userId:string;joinedAt:string } interface Learner { userId:string;name:string;email:string } interface Template { id:number;title:string;questions:number } interface Result { id:number;userId:string;score:number;correct:number;total:number;submittedAt:string|null }
const blank=<T,>():Page<T>=>({content:[],number:0,totalElements:0,totalPages:0})
const classes=ref<Page<Classroom>>(blank()),selected=ref<Classroom>(),members=ref<Page<Member>>(blank()),assignments=ref<Page<Assignment>>(blank()),learners=ref<Page<Learner>>(blank()),names=ref<Record<string,Learner>>({}),templates=ref<Page<Template>>(blank()),results=ref<Page<Result>>(blank()),selectedAssignment=ref<Assignment>(),review=ref<Attempt>(),comments=ref<Feedback[]>([])
const draft=reactive({name:'',description:'',courseId:null as number|null}),form=reactive({title:'',templateId:null as number|null,kind:'EXAM',minutes:30,startsAt:'',dueAt:''}),search=ref(''),choices=ref<string[]>([]),note=ref(''),questionId=ref<number|null>(null),busy=ref(false),error=ref(''),message=ref(''),courses=ref<Array<{courseId:number;courseName:string}>>([])
const selectionRequest=useLatestRequest(),searchRequest=useLatestRequest()
const base='/api/nihongo-user/staff'
async function action(work:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await work()}catch(cause){error.value=featureError(cause)}finally{busy.value=false}}
async function load(page=0){classes.value=await readFeature(`${base}/classrooms`,{page})}
async function select(row:Classroom){const pending=selectionRequest.begin();selected.value=row;selectedAssignment.value=undefined;review.value=undefined;results.value=blank();choices.value=[];error.value='';try{const [m,a]=await Promise.all([readFeature<Page<Member>>(`${base}/classrooms/${row.id}/members`,{},pending.signal),readFeature<Page<Assignment>>(`${base}/classrooms/${row.id}/assignments`,{},pending.signal)]);if(pending.isCurrent()){members.value=m;assignments.value=a;await loadNames(m.content.map(member=>member.userId))}}catch(cause){if(pending.isCurrent())error.value=featureError(cause)}}
async function loadNames(ids:string[]){if(ids.length){const people=await readFeature<Learner[]>('/api/users/staff/learners',{ids:ids.join(',')});names.value={...names.value,...Object.fromEntries(people.map(p=>[p.userId,p]))}}}
const create=()=>action(async()=>{const row=await writeFeature<Classroom>(`${base}/classrooms`,draft);draft.name='';draft.description='';await load();await select(row);message.value='Đã tạo lớp.'})
const archive=()=>action(async()=>{if(!selected.value)return;const row=(await gatewayUrl.put<Classroom>(`${base}/classrooms/${selected.value.id}`,{archived:!selected.value.archived,version:selected.value.version})).data;await load();await select(row)})
async function memberPage(page:number){if(!selected.value)return;members.value=await readFeature(`${base}/classrooms/${selected.value.id}/members`,{page});await loadNames(members.value.content.map(m=>m.userId))}
async function findLearners(page=0){const pending=searchRequest.begin();try{const data=await readFeature<Page<Learner>>('/api/users/staff/learners/search',{search:search.value,page},pending.signal);if(pending.isCurrent())learners.value=data}catch(cause){if(pending.isCurrent())error.value=featureError(cause)}}
const add=()=>action(async()=>{if(!selected.value)return;await writeFeature(`${base}/classrooms/${selected.value.id}/members`,{ids:choices.value});choices.value=[];await memberPage(0);message.value='Đã thêm học viên.'})
const remove=(id:string)=>action(async()=>{if(!selected.value||!confirm('Bỏ học viên khỏi lớp? Bài đã bắt đầu vẫn có thể hoàn tất đến hạn.'))return;await gatewayUrl.delete(`${base}/classrooms/${selected.value.id}/members/${id}`);await memberPage(members.value.number)})
async function templatePage(page=0){templates.value=await readFeature('/api/staff/content/exams',{page})}
async function assignmentPage(page=0){if(selected.value)assignments.value=await readFeature(`${base}/classrooms/${selected.value.id}/assignments`,{page})}
const assign=()=>action(async()=>{if(!selected.value)return;await writeFeature(`${base}/classrooms/${selected.value.id}/assignments`,form);await assignmentPage();message.value='Đã lưu bản nháp. Bấm Giao đề để học viên nhìn thấy.'})
const publish=(row:Assignment)=>action(async()=>{await writeFeature(`${base}/assignments/${row.id}/publish`,{version:row.version});await assignmentPage(assignments.value.number);message.value='Đã giao đề.'})
async function showResults(row:Assignment,page=0){selectedAssignment.value=row;review.value=undefined;results.value=await readFeature(`${base}/assignments/${row.id}/results`,{page});await loadNames(results.value.content.map(r=>r.userId))}
async function inspect(id:number){review.value=await readFeature(`${base}/attempts/${id}`);comments.value=(await readFeature<Page<Feedback>>(`${base}/attempts/${id}/feedback`)).content;note.value='';questionId.value=null}
const comment=()=>action(async()=>{if(!review.value)return;await writeFeature(`${base}/attempts/${review.value.id}/feedback`,{questionId:questionId.value,text:note.value});comments.value=(await readFeature<Page<Feedback>>(`${base}/attempts/${review.value.id}/feedback`)).content;note.value='';message.value='Đã gửi nhận xét cho học viên.'})
onMounted(()=>action(async()=>{await Promise.all([load(),templatePage(),findLearners(),readFeature<typeof courses.value>('/api/nihongo-user/courses').then(data=>{courses.value=data})])}))
</script>
<template><div class="ops-page"><header class="ops-heading"><div><h1>Lớp học & giao đề</h1><p>Staff quản lý lớp mình phụ trách; Admin có thể quản lý mọi lớp.</p></div></header><p v-if="error" class="ops-error" role="alert">{{ error }}</p><p v-if="message" class="ops-success" role="status">{{ message }}</p><form class="ops-panel ops-form" @submit.prevent="create"><h2 class="wide">Tạo lớp / nhóm</h2><label>Tên lớp<input v-model="draft.name" required maxlength="200"></label><label>Khóa học<select v-model="draft.courseId"><option :value="null">Nhóm chung theo quyền học</option><option v-for="course in courses" :key="course.courseId" :value="course.courseId">{{ course.courseName }}</option></select></label><label class="wide">Mô tả<textarea v-model="draft.description" maxlength="1000"></textarea></label><button class="ops-button" :disabled="busy">Tạo lớp</button></form><section class="ops-panel"><h2>Các lớp</h2><div class="ops-actions"><button v-for="row in classes.content" :key="row.id" class="ops-button" :class="{secondary:selected?.id!==row.id}" @click="select(row)">{{ row.name }} {{ row.archived?'(lưu trữ)':'' }}</button></div><OpsPager :page="classes.number" :total-pages="classes.totalPages" :total-elements="classes.totalElements" :busy="busy" @change="load" /></section><template v-if="selected"><section class="ops-panel"><div class="ops-heading"><h2>{{ selected.name }} · Học viên</h2><button class="ops-button secondary" :disabled="busy" @click="archive">{{ selected.archived?'Mở lại lớp':'Lưu trữ lớp' }}</button></div><form class="ops-actions" @submit.prevent="findLearners()"><input v-model="search" placeholder="Tên hoặc email học viên" maxlength="100"><button class="ops-button secondary">Tìm học viên</button></form><div v-if="!selected.archived" class="ops-grid"><label v-for="learner in learners.content" :key="learner.userId" class="ops-panel"><input v-model="choices" type="checkbox" :value="learner.userId"> {{ learner.name }} · {{ learner.email }}</label></div><OpsPager :page="learners.number" :total-pages="learners.totalPages" :total-elements="learners.totalElements" :busy="busy" @change="findLearners" /><button v-if="!selected.archived" class="ops-button" :disabled="busy||!choices.length" @click="add">Thêm {{ choices.length }} học viên</button><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>Học viên</th><th>Email</th><th>Thao tác</th></tr></thead><tbody><tr v-for="member in members.content" :key="member.id"><td>{{ names[member.userId]?.name || member.userId }}</td><td>{{ names[member.userId]?.email }}</td><td><button class="ops-button secondary" :disabled="busy" @click="remove(member.userId)">Bỏ khỏi lớp</button></td></tr></tbody></table></div><OpsPager :page="members.number" :total-pages="members.totalPages" :total-elements="members.totalElements" :busy="busy" @change="memberPage" /></section><form v-if="!selected.archived" class="ops-panel ops-form" @submit.prevent="assign"><h2 class="wide">Giao bài / đề thi</h2><label>Tiêu đề<input v-model="form.title" required maxlength="200"></label><label>Đề từ ngân hàng<select v-model="form.templateId" required><option :value="null" disabled>Chọn đề</option><option v-for="template in templates.content" :key="template.id" :value="template.id">{{ template.title }} · {{ template.questions }} câu</option></select></label><div class="wide"><OpsPager :page="templates.number" :total-pages="templates.totalPages" :total-elements="templates.totalElements" :busy="busy" @change="templatePage" /></div><label>Loại<select v-model="form.kind"><option value="EXAM">Thi online</option><option value="HOMEWORK">Bài tập về nhà</option></select></label><label v-if="form.kind==='EXAM'">Thời lượng (phút)<input v-model.number="form.minutes" type="number" min="1" max="180" required></label><label>Mở lúc<input v-model="form.startsAt" type="datetime-local" required></label><label>Hạn nộp<input v-model="form.dueAt" type="datetime-local" required></label><p class="ops-muted wide">Giờ theo múi giờ máy chủ. Đề là bản lưu cố định; học viên cần quyền học cấp độ trong đề. Thi chỉ mở đáp án sau hạn làm.</p><button class="ops-button" :disabled="busy">Lưu bản nháp</button></form><section class="ops-panel"><h2>Bài đã giao / bản nháp</h2><table class="ops-table"><thead><tr><th>Đề</th><th>Hạn</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><tr v-for="row in assignments.content" :key="row.id"><td>{{ row.title }}</td><td>{{ new Date(row.dueAt).toLocaleString('vi-VN') }}</td><td>{{ row.published?'Đã giao':'Bản nháp' }}</td><td><button v-if="!row.published" class="ops-button" :disabled="busy" @click="publish(row)">Giao đề</button> <button class="ops-button secondary" @click="showResults(row)">Bài làm & nhận xét</button></td></tr></tbody></table><OpsPager :page="assignments.number" :total-pages="assignments.totalPages" :total-elements="assignments.totalElements" :busy="busy" @change="assignmentPage" /></section></template><section v-if="selectedAssignment" class="ops-panel"><h2>Kết quả · {{ selectedAssignment.title }}</h2><table class="ops-table"><thead><tr><th>Học viên</th><th>Điểm</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr v-for="row in results.content" :key="row.id"><td>{{ names[row.userId]?.name || row.userId }}</td><td>{{ row.submittedAt?row.score:'—' }}</td><td>{{ row.submittedAt?'Đã nộp':'Đang làm' }}</td><td><button class="ops-button secondary" @click="inspect(row.id)">Xem bài</button></td></tr></tbody></table><OpsPager :page="results.number" :total-pages="results.totalPages" :total-elements="results.totalElements" :busy="busy" @change="page=>selectedAssignment && showResults(selectedAssignment,page)" /></section><section v-if="review" class="ops-panel"><h2>Bài làm {{ review.id }} · {{ review.score }} điểm</h2><article v-for="(q,index) in review.questions" :key="q.id"><strong>Câu {{ index+1 }}</strong><p class="ops-content">{{ plain(q.content) }}</p><p>Chọn {{ q.chosen || '—' }} · Đúng {{ q.correctAnswer }}</p></article><form v-if="review.finished" class="ops-form" @submit.prevent="comment"><label>Phạm vi<select v-model="questionId"><option :value="null">Nhận xét chung</option><option v-for="(q,index) in review.questions" :key="q.id" :value="q.id">Câu {{ index+1 }}</option></select></label><label class="wide">Nhận xét<textarea v-model="note" required maxlength="2000"></textarea></label><button class="ops-button" :disabled="busy">Gửi nhận xét</button></form><article v-for="entry in comments" :key="entry.id"><strong>{{ entry.questionId ? `Câu ${entry.questionId}` : 'Chung' }}</strong><p>{{ entry.text }}</p></article></section></div></template>
